def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my, opp = zip(*history)
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_my = my[-1]
    last_opp = opp[-1]
    # detect unconditional cooperator: exploit hard late
    if opp_d == 0:
        if n >= 90:
            return 'D'
        if n >= 60 and rng.random() < 0.15:
            return 'D'
        return 'C'
    # detect unconditional defector
    if opp_c == 0:
        return 'D'
    # near end, exploit if opponent mostly cooperative
    if n >= 95:
        if opp_c >= 2 * opp_d:
            return 'D'
        return 'D' if last_opp == 'D' else 'C'
    # recent window
    w = history[-12:]
    rc = sum(1 for _, o in w if o == 'C')
    rlen = len(w)
    rdef = rlen - rc
    # opponent defecting almost all recent -> defect
    if rlen >= 6 and rdef >= rlen - 1:
        return 'D'
    # opponent cooperating almost all recent -> mostly cooperate, rare probe
    if rlen >= 8 and rc >= rlen - 1:
        if n >= 30 and rng.random() < 0.08:
            return 'D'
        return 'C'
    # react to last moves
    if last_opp == 'D':
        # if we defected last time and opp still defecting -> keep punishing briefly
        if last_my == 'D':
            if n >= 3 and opp[-2] == 'D' and opp[-3] == 'D':
                return 'D'
            # avoid endless DD by testing cooperation
            if opp_c * 2 >= opp_d and rng.random() < 0.4:
                return 'C'
            return 'D'
        # fresh defection: retaliate
        # but if opponent is generally cooperative, forgive more readily
        if opp_c >= 3 * opp_d and rlen >= 4 and rc >= rlen - 2:
            if rng.random() < 0.5:
                return 'C'
        return 'D'
    # opponent cooperated last
    # long-run very cooperative opponent, opportunistically defect a bit
    if opp_c >= 4 * opp_d and n >= 25:
        if rng.random() < 0.12:
            return 'D'
        return 'C'
    # moderately cooperative opponent -> cooperate
    if opp_c >= opp_d:
        return 'C'
    # opponent more defective overall: only cooperate if recent trend is good
    if rlen >= 6 and rc >= rlen - 1:
        return 'C'
    return 'D'
